<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Configuration;use App\Application\Audit\AuditWriter;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class RegulatoryConfigurationController{
public function show(Request$r,string$code){$d=$r->validate(['jurisdiction'=>'nullable|string|size:2']);$row=DB::table('regulatory_reference_sets')->where(['jurisdiction'=>$d['jurisdiction']??'CM','code'=>$code,'status'=>'ACTIVE'])->first();abort_unless($row,404);return response()->json(['data'=>['code'=>$row->code,'jurisdiction'=>$row->jurisdiction,'version'=>$row->version,'entries'=>json_decode($row->entries,true)]]);}
public function store(Request$r,\App\Application\Configuration\RegulatoryReferenceSetService$sets){$d=$r->validate(['jurisdiction'=>'required|string|size:2','code'=>'required|string|max:80','effective_from'=>'required|date','effective_until'=>'nullable|date|after:effective_from','entries'=>'required|array|min:1']);return response()->json(['data'=>$sets->draft($d)],201);}
public function approve(Request$r,string$set,\App\Application\Configuration\RegulatoryReferenceSetService$sets){$r->validate(['reason'=>'required|string|min:20|max:2000']);return response()->json(['data'=>$sets->approve($set,$r->user())]);}}
